      "issue_id": "C3",
      "question": "What ownership model will be established for the accuracy and consistency of influence scores?",
      "why_it_matters": "Clear responsibility is needed to maintain score integrity as personnel change.",
      "decision_owner": "Management Team",
      "options": [
        "Designate a specific role for score oversight",
        "Implement a rotating review committee",
        "Establish a shared responsibility among coordinators"
      ],
